// Keep these imports outside the page bundle so they read the external image
// registry rather than the options inlined into the page bundle.
const { getImageProps } = require('next/image')

exports.initialProps = getImageProps({
  src: '/assets/probe.png',
  alt: 'module-scope',
  fill: true,
})

exports.ExternalImage = require('next/image').default
exports.ExternalLegacyImage = require('next/legacy/image').default
